(function () {
'use strict';
var KEY = 'cxb_b2b_archive_view';
var VALID = ['cols3', 'cols4', 'compact', 'list'];
function read() {
try {
var v = window.localStorage.getItem(KEY);
return VALID.indexOf(v) > -1 ? v : null;
} catch (e) {
return null;
}
}
function write(v) {
try {
window.localStorage.setItem(KEY, v);
} catch (e) { /* 同上 */ }
}
function apply(view) {
if (VALID.indexOf(view) === -1) {
document.documentElement.removeAttribute('data-cxb-view');
return;
}
document.documentElement.setAttribute('data-cxb-view', view);
}
function mobileHidden() {
var cfg = window.cxbArchiveLayout;
return !!(cfg && cfg.mobileHidden);
}
function isNarrow() {
return !!(window.matchMedia && window.matchMedia('(max-width: 768px)').matches);
}
var saved = read();
/*
* 手机端隐藏工具条时，不套用记住的排列。
*
* 只把工具条 display:none 掉的话，访客在电脑上选的「列表」会跟到手机上，
* 而手机上已经没有任何地方能改回来 —— 等于把人锁在一个他当下没得选的
* 版式里。既然控件不给用，版式就该回到后台设置的默认列数。
*
* localStorage 里的值不清：那是访客在电脑端的选择，回到电脑上仍然有效。
*/
if (saved && !(mobileHidden() && isNarrow())) {
apply(saved);
}
function boot() {
var toolbar = document.querySelector('[data-cxb-archive-toolbar]');
if (!toolbar) {
/*
* 后台关掉了工具条，但 localStorage 里可能还留着上次的选择。
* 不清掉的话，一个「已关闭」的功能仍在改变页面排版，而访客
* 已经没有任何界面可以把它改回来。
*/
apply(null);
try {
window.localStorage.removeItem(KEY);
} catch (e) { /* ignore */ }
return;
}
var buttons = Array.prototype.slice.call(
toolbar.querySelectorAll('.cxb-b2b-archive-view-btn')
);
/*
* 没选过时，高亮哪一个？
*
* 网格此刻用的是后台设置的列数（模板输出的 .cxb-b2b-columns-N）。
* 若那个值正好是 3 或 4，就高亮对应按钮；否则（1/2/5/6 列）四个按钮
* 都不亮——因为当前排列确实不是它们中的任何一个，随便点亮一个是在
* 撒谎，访客会以为自己已经选了。
*/
function currentView() {
var v = document.documentElement.getAttribute('data-cxb-view');
if (VALID.indexOf(v) > -1) {
return v;
}
var cols = parseInt(toolbar.getAttribute('data-default-cols'), 10);
if (cols === 3) { return 'cols3'; }
if (cols === 4) { return 'cols4'; }
return null;
}
function syncButtons() {
var active = currentView();
buttons.forEach(function (btn) {
var on = btn.getAttribute('data-cxb-view') === active;
btn.setAttribute('aria-pressed', on ? 'true' : 'false');
});
}
buttons.forEach(function (btn) {
btn.addEventListener('click', function (e) {
e.preventDefault();
var view = btn.getAttribute('data-cxb-view');
if (VALID.indexOf(view) === -1) {
return;
}
apply(view);
write(view);
syncButtons();
});
});
syncButtons();
/*
* 横向筛选器一旦筛过，工具条上的总数就不再成立。
*
* 那个数字是服务端渲染时的 found_posts（全部产品）。筛选器走 AJAX
* 换掉网格内容后，屏幕上会同时出现两个互相矛盾的数字：筛选器自己的
* 「找到 N 件」和工具条的「共 M 件产品」。
*
* 与其去解析筛选器那句本地化文案里的数字（换个语言就失效），不如在
* 它接管网格的那一刻把工具条的总数收起来——此时权威数字是筛选器给的
* 那个。显示一个过时的数字比不显示更糟。
*
* 用 childList 而不是别的信号：frontend.js 的 cxbfWriteGrid() 是
* $grid.html(newHtml)，必然触发子节点替换，这是最可靠的一处。
*/
var grid = document.querySelector('.cxb-b2b-products-grid');
var count = toolbar.querySelector('.cxb-b2b-archive-toolbar-count');
if (grid && count && window.MutationObserver) {
var gridObserver = new MutationObserver(function () {
count.hidden = true;
gridObserver.disconnect(); // 收起来就不用再看了
});
gridObserver.observe(grid, { childList: true });
}
/*
* 两个下拉的每一项 value 都是服务端算好的完整地址（已把 paged 清掉，
* 回到第 1 页），这里只负责跳过去。
*
* 不在这里拼 URL：分页有 /page/N/ 和 ?paged=N 两种形式，还要保留
* 筛选器带来的其它参数，PHP 那边已经处理完了，前端再拼一遍就是
* 同一套规则维护两份。
*/
var selects = toolbar.querySelectorAll('[data-cxb-nav-select]');
Array.prototype.forEach.call(selects, function (select) {
select.addEventListener('change', function () {
var url = select.value;
if (url) {
window.location.href = url;
}
});
});
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', boot);
} else {
boot();
}
})();
